## Stable IDs equal array indices for this fixed-population milestone.
var count: int = 0
var positions := PackedVector2Array()
var previous := PackedVector2Array()
var velocities := PackedVector2Array()
var next_velocities := PackedVector2Array()
var directions := PackedInt32Array()
var groups := PackedInt32Array()
var crossings: int = 0

func allocate(size: int) -> void:
	count = size
	positions.resize(size)
	previous.resize(size)
	velocities.resize(size)
	next_velocities.resize(size)
	directions.resize(size)
	groups.resize(size)
	crossings = 0

scripts/simulation/benchmark_scenario.gd:
extends RefCounted
const WORLD := Vector2(1600, 900)
const RADIUS: float = 5.0
const SPEED: float = 65.0
var kind: String = "dispersed"
var obstacles: Array[Rect2] = []

func configure(value: String) -> void:
	kind = value
	obstacles.clear()
	if kind == "chokepoint":
		obstacles.append(Rect2(780, 20, 40, 350))
		obstacles.append(Rect2(780, 530, 40, 350))

func spawn_point(index: int, count: int, random: RandomNumberGenerator) -> Vector2:
	var half := ceili(float(count) * 0.5)
	var local_index := index % half
	var columns := ceili(sqrt(float(half) * 0.65))
	var rows := ceili(float(half) / float(columns))
	var left := index < half
	var origin := Vector2(60 if left else 850, 70)
	var size := Vector2(690, 760)
	if kind == "chokepoint":
		origin.x = 400 if left else 850
		size.x = 350
	return origin + Vector2(
		(float(local_index % columns) + 0.5) / float(columns) * size.x,
		(float(floori(float(local_index) / float(columns))) + 0.5) / float(rows) * size.y
	) + Vector2(random.randf_range(-1, 1), random.randf_range(-1, 1))

func destination(point: Vector2, direction: int, index: int) -> Vector2:
	var target_y := 80.0 + float((index * 73) % 740)
	if kind == "chokepoint":
		var before_gate := point.x < 850.0 if direction > 0 else point.x > 750.0
		if before_gate:
			# Separate opposite flows into lanes, still sharing one narrow opening.
			target_y = (418.0 if direction > 0 else 482.0) + float(index % 5 - 2) * 9.0
			return Vector2(870 if direction > 0 else 730, target_y)
	return Vector2(1530 if direction > 0 else 70, target_y)

func constrain(point: Vector2) -> Vector2:
	var result := point.clamp(Vector2(20 + RADIUS, 20 + RADIUS), WORLD - Vector2(20 + RADIUS, 20 + RADIUS))
	for obstacle in obstacles:
		var expanded := obstacle.grow(RADIUS)
		if expanded.has_point(result):
			var distances := Vector4(result.x - expanded.position.x, expanded.end.x - result.x, result.y - expanded.position.y, expanded.end.y - result.y)
			var nearest := minf(minf(distances.x, distances.y), minf(distances.z, distances.w))
			if nearest == distances.x:
				result.x = expanded.position.x - 0.001
			elif nearest == distances.y:
				result.x = expanded.end.x + 0.001
			elif nearest == distances.z:
				result.y = expanded.position.y - 0.001
			else:
				result.y = expanded.end.y + 0.001
	return result

func is_valid(point: Vector2) -> bool:
	if not point.is_finite() or point.x < 25.0 or point.x > 1575.0 or point.y < 25.0 or point.y > 875.0:
		return false
	for obstacle in obstacles:
		if obstacle.grow(RADIUS - 0.01).has_point(point):
			return false
	return true

scripts/navigation/spatial_grid.gd:
extends RefCounted
## Dense linked-cell grid: bounded O(cells + agents) rebuild, no per-query arrays.
const CELL_SIZE: float = 22.0
var columns: int = 0
var rows: int = 0
var heads := PackedInt32Array()
var links := PackedInt32Array()
var candidates := PackedInt32Array()
var neighbor_cells := PackedInt32Array()
var neighbor_counts := PackedInt32Array()
var candidate_checks: int = 0

func configure(size: Vector2, capacity: int) -> void:
	columns = ceili(size.x / CELL_SIZE)
	rows = ceili(size.y / CELL_SIZE)
	heads.resize(columns * rows)
	links.resize(capacity)
	candidates.resize(capacity)
	neighbor_cells.resize(columns * rows * 9)
	neighbor_counts.resize(columns * rows)
	for y in range(rows):
		for x in range(columns):
			var cell := y * columns + x
			var count: int = 0
			for dy in range(-1, 2):
				for dx in range(-1, 2):
					var nx := x + dx
					var ny := y + dy
					if nx >= 0 and nx < columns and ny >= 0 and ny < rows:
						neighbor_cells[cell * 9 + count] = ny * columns + nx
						count += 1
			neighbor_counts[cell] = count

func cell_of(point: Vector2) -> int:
	return clampi(floori(point.y / CELL_SIZE), 0, rows - 1) * columns + clampi(floori(point.x / CELL_SIZE), 0, columns - 1)

func rebuild(positions: PackedVector2Array) -> void:
	heads.fill(-1)
	for i in range(positions.size()):
		var cell := cell_of(positions[i])
		links[i] = heads[cell]
		heads[cell] = i

func gather(point: Vector2) -> int:
	var cell := cell_of(point)
	var count: int = 0
	for n in range(neighbor_counts[cell]):
		var other := heads[neighbor_cells[cell * 9 + n]]
		while other != -1:
			candidates[count] = other
			count += 1
			other = links[other]
	candidate_checks += count
	return count

scripts/simulation/crowd_movement.gd:
extends RefCounted
const State = preload("res://scripts/simulation/crowd_state.gd")
const Grid = preload("res://scripts/navigation/spatial_grid.gd")
const Scenario = preload("res://scripts/simulation/benchmark_scenario.gd")
var collision_corrections: int = 0

func integrate(state: State, grid: Grid, scenario: Scenario, delta: float) -> void:
	for i in range(state.count):
		var point := state.positions[i]
		if point.x > 1510.0:
			state.directions[i] = -1
		elif point.x < 90.0:
			state.directions[i] = 1
		var goal := scenario.destination(point, state.directions[i], i)
		var desired := (goal - point).normalized() * Scenario.SPEED
		var separation := Vector2.ZERO
		var count := grid.gather(point)
		for n in range(count):
			var other := grid.candidates[n]
			if other == i:
				continue
			var offset := point - state.positions[other]
			var squared := offset.length_squared()
			if squared < 400.0 and squared > 0.000001:
				var distance := sqrt(squared)
				separation += offset / distance * (20.0 - distance) * 12.0
		state.next_velocities[i] = (desired + separation).limit_length(Scenario.SPEED)
	for i in range(state.count):
		state.previous[i] = state.positions[i]
		state.velocities[i] = state.next_velocities[i]
		state.positions[i] = scenario.constrain(state.positions[i] + state.velocities[i] * delta)

func separate(state: State, grid: Grid, scenario: Scenario) -> void:
	collision_corrections = 0
	for i in range(state.count):
		var point := state.positions[i]
		var count := grid.gather(point)
		for n in range(count):
			var other := grid.candidates[n]
			if other <= i:
				continue
			var offset := state.positions[i] - state.positions[other]
			var squared := offset.length_squared()
			if squared < 100.0:
				var distance := sqrt(squared)
				var normal := offset / distance if distance > 0.001 else Vector2.RIGHT
				var correction := normal * (10.0 - distance) * 0.5
				state.positions[i] = scenario.constrain(state.positions[i] + correction)
				state.positions[other] = scenario.constrain(state.positions[other] - correction)
				collision_corrections += 1

scripts/simulation/crowd_simulation.gd:
extends RefCounted
const State = preload("res://scripts/simulation/crowd_state.gd")
const Grid = preload("res://scripts/navigation/spatial_grid.gd")
const Movement = preload("res://scripts/simulation/crowd_movement.gd")
const Scenario = preload("res://scripts/simulation/benchmark_scenario.gd")
const FIXED_DELTA: float = 1.0 / 30.0
var state := State.new()
var grid := Grid.new()
var movement := Movement.new()
var scenario := Scenario.new()
var ticks: int = 0
var simulation_usec: int = 0
var grid_usec: int = 0
var movement_usec: int = 0
var separation_usec: int = 0

func reset(count: int, kind: String, random_seed: int = 20261112) -> void:
	assert(count > 0 and count <= 1000)
	state.allocate(count)
	scenario.configure(kind)
	grid.configure(Scenario.WORLD, count)
	var random := RandomNumberGenerator.new()
	random.seed = random_seed
	var half := ceili(float(count) * 0.5)
	for i in range(count):
		state.positions[i] = scenario.spawn_point(i, count, random)
		state.previous[i] = state.positions[i]
		state.velocities[i] = Vector2.ZERO
		state.directions[i] = 1 if i < half else -1
		state.groups[i] = i % 3
	ticks = 0
	grid.rebuild(state.positions)

func step(delta: float = FIXED_DELTA) -> void:
	var started := Time.get_ticks_usec()
	grid.candidate_checks = 0
	grid.rebuild(state.positions)
	var after_grid := Time.get_ticks_usec()
	movement.integrate(state, grid, scenario, delta)
	var after_movement := Time.get_ticks_usec()
	grid.rebuild(state.positions)
	var before_separation := Time.get_ticks_usec()
	movement.separate(state, grid, scenario)
	var finished := Time.get_ticks_usec()
	grid_usec = (after_grid - started) + (before_separation - after_movement)
	movement_usec = after_movement - after_grid
	separation_usec = finished - before_separation
	simulation_usec = finished - started
	for i in range(state.count):
		if (state.previous[i].x < 800.0 and state.positions[i].x >= 800.0) or (state.previous[i].x >= 800.0 and state.positions[i].x < 800.0):
			state.crossings += 1
	ticks += 1

func diagnostics() -> Dictionary:
	var invalid: int = 0
	var pairs: int = 0
	var max_penetration: float = 0.0
	var gate_population: int = 0
	grid.rebuild(state.positions)
	for i in range(state.count):
		var point := state.positions[i]
		if not scenario.is_valid(point):
			invalid += 1
		if absf(point.x - 800.0) < 100.0:
			gate_population += 1
		var count := grid.gather(point)
		for n in range(count):
			var other := grid.candidates[n]
			if other <= i:
				continue
			var distance := point.distance_to(state.positions[other])
			if distance < 9.9:
				pairs += 1
				max_penetration = maxf(max_penetration, 10.0 - distance)
	return {"count": state.count, "ticks": ticks, "invalid_positions": invalid, "overlap_pairs": pairs, "max_penetration": max_penetration, "gate_population": gate_population, "crossings": state.crossings, "candidate_checks": grid.candidate_checks}

scripts/rendering/crowd_renderer.gd:
extends Node2D
const State = preload("res://scripts/simulation/crowd_state.gd")
const Scenario = preload("res://scripts/simulation/benchmark_scenario.gd")
var state: State
var scenario: Scenario
var alpha: float = 0.0
var submission_usec: int = 0
var texture: ImageTexture
var colors := PackedColorArray()
var use_multimesh: bool = false
@onready var instances: MultiMeshInstance2D = $Instances

func configure(data: State, map: Scenario, instanced: bool = false) -> void:
	state = data
	scenario = map
	use_multimesh = instanced
	if texture == null:
		var image := Image.create(16, 16, false, Image.FORMAT_RGBA8)
		image.fill(Color.TRANSPARENT)
		for y in range(16):
			for x in range(16):
				if Vector2(x - 7.5, y - 7.5).length_squared() <= 56.25:
					image.set_pixel(x, y, Color.WHITE)
		texture = ImageTexture.create_from_image(image)
	colors.resize(state.count)
	var palette: Array[Color] = [Color("#56d9ce"), Color("#f3be5a"), Color("#ab8bf5")]
	for i in range(state.count):
		colors[i] = palette[state.groups[i]]
	var mesh := QuadMesh.new()
	mesh.size = Vector2(10, 10)
	var multimesh := MultiMesh.new()
	multimesh.transform_format = MultiMesh.TRANSFORM_2D
	multimesh.use_colors = true
	multimesh.mesh = mesh
	multimesh.instance_count = state.count
	multimesh.custom_aabb = AABB(Vector3.ZERO, Vector3(1600, 900, 1))
	instances.multimesh = multimesh
	instances.texture = texture
	instances.visible = use_multimesh
	for i in range(state.count):
		multimesh.set_instance_color(i, colors[i])
	queue_redraw()

func present(fraction: float) -> void:
	alpha = clampf(fraction, 0.0, 1.0)
	if use_multimesh:
		var started := Time.get_ticks_usec()
		for i in range(state.count):
			var point := state.previous[i].lerp(state.positions[i], alpha)
			instances.multimesh.set_instance_transform_2d(i, Transform2D(0.0, point))
		submission_usec = Time.get_ticks_usec() - started
	queue_redraw()

func _draw() -> void:
	draw_rect(Rect2(Vector2.ZERO, Scenario.WORLD), Color("#101824"))
	draw_rect(Rect2(20, 20, 1560, 860), Color("#243249"), false, 2)
	if state == null:
		return
	for obstacle in scenario.obstacles:
		draw_rect(obstacle, Color("#536277"))
	if not use_multimesh:
		var started := Time.get_ticks_usec()
		for i in range(state.count):
			var point := state.previous[i].lerp(state.positions[i], alpha)
			draw_texture_rect(texture, Rect2(point - Vector2(5, 5), Vector2(10, 10)), false, colors[i])
		submission_usec = Time.get_ticks_usec() - started

scripts/benchmarks/benchmark_recorder.gd:
extends RefCounted
## Wall-clock frame intervals include pacing; CPU spans measure only simulation code.
var frames := PackedFloat64Array()
var simulation := PackedFloat64Array()
var grid := PackedFloat64Array()
var movement := PackedFloat64Array()
var separation := PackedFloat64Array()
var rendering := PackedFloat64Array()
var memory := PackedFloat64Array()
var started_usec: int = 0
var previous_usec: int = 0

func begin() -> void:
	frames.clear()
	simulation.clear()
	grid.clear()
	movement.clear()
	separation.clear()
	rendering.clear()
	memory.clear()
	started_usec = Time.get_ticks_usec()
	previous_usec = started_usec

func frame(render_usec: int) -> void:
	var now := Time.get_ticks_usec()
	frames.append(float(now - previous_usec) / 1000.0)
	previous_usec = now
	rendering.append(float(render_usec) / 1000.0)
	if frames.size() % 30 == 0:
		memory.append(float(OS.get_static_memory_usage()) / 1048576.0)

func tick(sim_usec: int, grid_usec: int, move_usec: int, separation_usec: int) -> void:
	simulation.append(float(sim_usec) / 1000.0)
	grid.append(float(grid_usec) / 1000.0)
	movement.append(float(move_usec) / 1000.0)
	separation.append(float(separation_usec) / 1000.0)

func stats(values: PackedFloat64Array) -> Dictionary:
	if values.is_empty():
		return {}
	var sorted := values.duplicate()
	sorted.sort()
	var total: float = 0.0
	for value in values:
		total += value
	return {"mean": total / values.size(), "median": sorted[floori(float(sorted.size() - 1) * 0.5)], "p95": sorted[ceili(float(sorted.size() - 1) * 0.95)], "p99": sorted[ceili(float(sorted.size() - 1) * 0.99)], "max": sorted[-1], "min": sorted[0], "samples": values.size()}

func finish() -> Dictionary:
	var frame_stats := stats(frames)
	var elapsed := float(Time.get_ticks_usec() - started_usec) / 1000000.0
	return {"duration_seconds": elapsed, "fps": float(frames.size()) / elapsed, "frame_ms": frame_stats, "simulation_tick_ms": stats(simulation), "grid_tick_ms": stats(grid), "movement_tick_ms": stats(movement), "separation_tick_ms": stats(separation), "render_submission_ms": stats(rendering), "static_memory_mib": stats(memory), "static_memory_first_mib": memory[0] if not memory.is_empty() else 0.0, "static_memory_last_mib": memory[-1] if not memory.is_empty() else 0.0, "raw_frame_ms": Array(frames), "raw_simulation_tick_ms": Array(simulation), "raw_memory_mib": Array(memory)}
